WITH matched_keys AS (SELECT id, city FROM suppliers INTERSECT ALL SELECT id, city FROM suppliers WHERE city != 'Tokyo'), kept_rows AS (SELECT s.* FROM suppliers s JOIN matched_keys k ON s.id = k.id AND s.city = k.city) SELECT id, supplier_name, country, city, CASE WHEN country RLIKE '^(UK|SG)$' THEN 'GROUP_B' WHEN country RLIKE '^(TH|US)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS country_zone FROM kept_rows
